// Counters: damage multiplier of an attacker type (cl) against a target type (tg: inf, veh, air). Not listed = x1.
// - snipers pick off infantry; the Assault Trooper's rotary machine gun shreds infantry; tanks roll over infantry
// - rocket artillery pounds everything on the ground (infantry and vehicles)
// - attack helicopters hunt vehicles (tanks, carriers, artillery)
// - gunships rule the sky: they shoot down helicopters and drones, and hit vehicles hard
// - rifles hit aircraft normally, the rotary gun and snipers a bit less; tanks and artillery can hardly aim at the sky; the carrier only transports
const VS = {
  inf:{},
  snp:{inf:1.5, veh:0.5, air:0.7},
  shk:{inf:1.4, veh:0.8, air:0.9},
  veh:{inf:1.3, air:0.5},
  trp:{air:0.5},
  art:{inf:1.2, veh:1.3, air:0.3},
  heli:{veh:1.5, air:0.8},
  gsh:{air:1.6, veh:1.2},
  mst:{veh:1.6, inf:1.1, air:0.4},   // Mastodon Tank: its twin cannons crush vehicles, but it can hardly aim at the sky
};
const vsMul = (cl, tg) => (VS[cl] && VS[cl][tg]) || 1;
const TG_NAME = {inf:'Infantry', veh:'Vehicles', air:'Air units'};
// strong against (kinds of targets) / weak against (the real troops that counter it), shown on the unit cards (not for the truck and the drone, which do not fight)
// what each troop is good at, shown on every card
const UNIT_ROLE = {recruit:'Cheap and quick to train: strength in numbers.', rifleman:'Very tough thanks to its shield: holds the line in defense.',
  sniper:'Fires first, from long range (opening volley).', assault:'Its rotary machine gun shreds infantry.', truck:'Brings back a lot of loot.',
  drone:'Very fast: spies on enemy bases.', apc:'Very tough, and brings back a lot of loot.', tank:'Very tough and powerful: crushes infantry.',
  artillery:'Fires first, from very long range (opening volley).', heli:'Fast: hunts vehicles.', gunship:'Rules the sky and hits vehicles hard.',
  mastodon:'Crushes vehicles. Defense +30% when it defends your main base.'};
function counterInfo(u){ const d=UNITS[u], role=UNIT_ROLE[u]?`<span class="good">${IC.star} ${_t('Strength: {t}',{t:_t(UNIT_ROLE[u])})}</span>`:'';
  if(d.at<10) return role?`<div class="ucnt">${role}</div>`:'';
  const strong=Object.keys(TG_NAME).filter(t=>vsMul(d.cl,t)>1).map(t=>_t(TG_NAME[t]));
  const weak=Object.keys(UNITS).filter(v=>v!==u && UNITS[v].at>=10 && vsMul(UNITS[v].cl,d.tg)>1).map(v=>_t(UNITS[v].name));
  return `<div class="ucnt">${role}${strong.length?`<span class="good">${IC.atk} ${_t('Strong against: {l}',{l:strong.join(', ')})}</span>`:''}${weak.length?`<span class="bad">${IC.warn} ${_t('Weak against: {l}',{l:weak.join(', ')})}</span>`:''}</div>`; }
const UNIT_ORDER = Object.keys(UNITS);
for(const u in UNITS) UNITS[u].img = UIMG[u].img;
const TRAINERS = ['barracks','factory','helipad'];
const trainQty = {};

// ===== ECONOMY =====
const lvlIn = (S,t) => { let m=0; for(const k in S){ const b=S[k]; if(b.type===t) m=Math.max(m,b.lvl); } return m; };
const countIn = (S,t) => { let n=0; for(const k in S) if(S[k].type===t) n++; return n; };
// buildings that only matter in the main base (research, Titan, radar, marches, storage): always read there, even while the outpost is shown
const MAIN_ONLY = new Set(['command','lab','radar','hangar','rally','warehouse']);
const bldLevel = t => lvlIn(MAIN_ONLY.has(t) ? slotsOf('main') : state.slots, t);
function popMax(){ let p=100+lvlIn(slotsOf('main'),'command')*50; for(const S of allSlots()) for(const k in S){ const b=S[k]; if(b.type==='housing') p+=b.lvl*100; } return p; }   // the Housing Blocks of both bases make one shared population
function queuedUnits(){ const q={}; for(const T of allTraining()) for(const bl in T) for(const j of T[bl]) q[j.u]=(q[j.u]||0)+j.n; return q; }   // both bases
function marching(){ const o={}; for(const m of (state.marches||[])) for(const u in m.troops) o[u]=(o[u]||0)+m.troops[u]; return o; }
// like Dragons of Atlantis: population is the workforce used while troops are being trained; it comes back when training is over
const popFree = () => Math.max(0, popMax()-popUsed());   // what the bar shows: the workforce still available
function popUsed(){ let p=0; const q=queuedUnits(); for(const u in q) p+=q[u]*UNITS[u].pop; return p; }
const goldIncome = () => Math.round(30 + popMax()*0.2);  // taxes paid by your population
function troopPower(){ let p=0; const mm=marching(), D=defenseState(); for(const u in UNITS) p+=((state.troops[u]||0)+(D[u]||0)+(mm[u]||0))*UNITS[u].power; return p; }
// every Garrison LEVEL speeds up all training (+3% each): upgrading counts as much as building more Garrisons
const garrisonLevels = () => { let n=0; for(const k in state.slots){ const b=state.slots[k]; if(b.type==='garrison') n+=b.lvl; } return n; };
const trainSpeed = bl => 1 + 0.05*bldLevel(bl) + 0.03*garrisonLevels() + techB('drill');
const TRAIN_SCALE = 4;   // Dragons of Atlantis pace: big orders take hours
const unitTime = (u,n) => Math.max(1, Math.round(UNITS[u].time*TRAIN_SCALE*n/trainSpeed(UNITS[u].bld)));
const UCOST = [...RES,'alloy'];   // what a troop can cost: the normal resources, and Heavy Alloy for the outpost troops
const resOf = r => state.res[r]||0;
function unitCost(u,n){ const o={}; for(const r of UCOST) o[r]=(UNITS[u].cost[r]||0)*n; return o; }
function maxTrain(u){ const d=UNITS[u]; let m=Math.floor((popMax()-popUsed())/d.pop);
  for(const r of UCOST){ const c=d.cost[r]||0; if(c) m=Math.min(m,Math.floor(resOf(r)/c)); } return Math.max(0,Math.min(m,99999)); }
function whyNotTrain(u,n){ const d=UNITS[u], lv=bldLevel(d.bld);
  if(d.base==='op'){ if(!state.op) return _t('Requires the Rampart outpost'); if(curBase()!=='op') return _t('Only in the Vehicle Factory of the outpost'); }
  if(!lv) return _t('Build a {b} first',{b:_t(B[d.bld].name)});
  if(lv<d.req) return _t('Requires {b} level {l}',{b:_t(B[d.bld].name),l:d.req});
  { const mt=missingTech(UNIT_TECH[u]); if(Object.keys(mt).length) return _t('Requires research: {r}',{r:techReqText(mt)}); }
  if(!(n>0)) return _t('Choose how many to train');
  if((state.training[d.bld]||[]).length>=5) return _t('Training queue full (5 orders max)');
  if(popUsed()+n*d.pop>popMax()) return _t('Not enough population: build or upgrade Housing Blocks');
  const c=unitCost(u,n); for(const r of UCOST) if(c[r] && resOf(r)<c[r]) return _t('Not enough resources');
  return ''; }
function train(u,n){
  if(whyNotTrain(u,n)) return; const d=UNITS[u], c=unitCost(u,n); for(const r of UCOST) if(c[r]) state.res[r]=resOf(r)-c[r];
  const q=state.training[d.bld]=state.training[d.bld]||[], now=Date.now(), st=q.length?Math.max(now,q[q.length-1].e):now;
  q.push({u,n,s:st,e:st+unitTime(u,n)*1000}); trainQty[u]=0; save(); renderAll(); toast(IC.troops+' '+_t('Training {n} {u}',{n:fmtI(n),u:_t(d.name)})); }
// cancel an order: one still waiting is fully refunded, the one being trained gives 80% back (like a construction); the next orders move forward
function cancelTrain(bl, i){
  const q=state.training[bl]; if(!q || !q[i]) return; const now=Date.now(), j=q[i], started=i===0 && now>=j.s, c=unitCost(j.u,j.n);
  for(const r of UCOST) if(c[r]) state.res[r]=resOf(r)+(started ? Math.floor(c[r]*0.8) : c[r]);
  q.splice(i,1); let t=i===0 ? now : q[i-1].e;
  for(let k=i;k<q.length;k++){ const dur=q[k].e-q[k].s; q[k].s=t; q[k].e=t+dur; t=q[k].e; }
  if(!q.length) delete state.training[bl];
  save(); renderAll(); toast(IC.ok+' '+_t(started?'Training cancelled (80% refunded)':'Order cancelled (fully refunded)')); }
let tcConfirm=null;   // a first tap on the cross asks for confirmation
function finishTraining(bl){ // test button: finishes the current order, the next ones move forward
  const q=state.training[bl]; if(!q||!q.length) return; const now=Date.now(); let t=now;
  q.forEach((j,i)=>{ const dur=j.e-j.s; if(i===0) j.e=now; else { j.s=t; j.e=t+dur; } t=j.e; }); checkTraining(); }
function checkTraining(){
  const now=Date.now(); let p0=null; const done=[];
  for(const bl in state.training){ const q=state.training[bl];
    while(q.length && now>=q[0].e){ if(p0===null) p0=totalPower(); const j=q.shift(); state.troops[j.u]=(state.troops[j.u]||0)+j.n; done.push(j); } }
  if(done.length){ save(); renderAll(); const j=done[done.length-1]; toast(IC.ok+' '+_t('{n} {u} ready',{n:fmtI(j.n),u:_t(UNITS[j.u].name)})); powerGain(totalPower()-p0); } }

