  const hl=playerLevel(totalPower()); if(hl!==lastHomeLvl){ lastHomeLvl=hl; invalidateCells([[state.pos.x,state.pos.y]]); }
  chunkMax=Math.max(40, (V.cx1-V.cx0+5)*(V.cy1-V.cy0+5));
