// =====================================================================
// ===== TITAN (our Great Dragon): levels, health, equipment, battles =====
// =====================================================================
const EQ_SLOTS = ['armor','weapon','reactor','legs'];
const EQ_NAME = {armor:'Armor Plate', weapon:'Arm Cannon', reactor:'Jet Reactor', legs:'Armored Legs'};
const PART_IMG = s => curBase()==='op' ? `assets/img/rempart_eq_${s}.webp` : `assets/img/eq_${s}_2.webp`;   // painted icons (Gemini) · Rampart skin in the outpost
const hangarLvl = () => lvlIn(state.slots, curBase()==='op' ? 'ophangar' : 'hangar');   // the hangar of the Titan of the active base
const titanName = () => _t(curBase()==='op' ? 'Rampart Titan' : 'Titan');
const hangarName = () => curBase()==='op' ? 'Rampart Hangar' : 'Titan Hangar';
const RP_CHANCE = 0.2;   // Rampart Titan: chance to find one of its missing armor pieces at each victory on a Fortified Mountain
// the Rampart Titan at home and fit to fight reinforces the Wall of the main base: +3% defense per level
const rempartGuard = () => state.op ? (withBase('op', ()=>titanReady() ? 0.03*titanState().lvl : 0) || 0) : 0;
function titanState(){ if(!state.titan) state.titan={lvl:1, xp:0, hp:100, away:false, parts:{}}; const T=state.titan; if(T.lvl>10) T.lvl=10;
  if(!T.parts) T.parts={};
  // old equipment system (tiers, inventory): each kind of part already found becomes an armor piece, the extra copies are paid in gold
  if(T.eq || T.inv){ let g=0; for(const it of [...Object.values(T.eq||{}), ...(T.inv||[])]){ if(!it || !EQ_NAME[it.s]) continue; if(T.parts[it.s]) g+=[0,150,600,2000][it.t]||0; else T.parts[it.s]=1; }
    delete T.eq; delete T.inv; if(g && state.res) state.res.gold=(state.res.gold||0)+g; }
  return T; }
const armorCount = () => EQ_SLOTS.filter(s=>titanState().parts[s]).length;
const armorDone = () => armorCount()===4;
const titanMax = () => Math.min(10, Math.max(1, hangarLvl()));   // like the Great Dragon: level capped by its hangar, 10 max
const xpNeed = L => Math.round(600*Math.pow(L,2.4));
const tScale = L => L*(1+0.25*(L-1));   // stats grow faster at high level (level 10 = x32.5)
function titanStats(){ const T=titanState(), L=tScale(T.lvl)*(1+techB('robotics'));
  // worth its power in battle, like any troop (on top of that it gives its attack bonus to the troops marching with it)
  return { at: Math.round(1700*L), df: 20, hp: Math.round(14000*L), sp: 380, ld: Math.round(300*L), rg:0, pw: Math.round(120*tScale(T.lvl)) }; }
const titanTroopBonus = () => 0.05*titanState().lvl;      // +5% attack for the troops marching with the Titan, per level (+50% at level 10)
const titanReady = () => { const T=titanState(); return hangarLvl()>0 && armorDone() && !T.away && T.hp>=30; };   // no battle without its full armor
const repairRate = () => 5 + 2*hangarLvl();         // health % repaired per hour at the hangar
function titanPower(){ if(!hangarLvl()) return 0; return titanStats().pw*PW_BASE; }   // the Titan of the active base   // the armor gives no power
function partIcon(s, got, size=46){ return `<span class="eqi${got?'':' empty'}" style="width:${size}px;height:${size}px;border-color:${got?'#f3c534':'#555'}"><img src="${PART_IMG(s)}" alt=""${got?'':' style="filter:grayscale(1) brightness(.45)"'}></span>`; }
function gainXp(n){ const T=titanState(); if(T.lvl>=titanMax()){ T.xp=Math.min(T.xp+n, xpNeed(T.lvl)); return 0; }
  T.xp+=n; let up=0; while(T.lvl<titanMax() && T.xp>=xpNeed(T.lvl)){ T.xp-=xpNeed(T.lvl); T.lvl++; up++; }
  if(up) toast(IC.titan_ic+' '+_t(curBase()==='op'?'Rampart Titan reached level {l}!':'Titan reached level {l}!',{l:T.lvl})); return up; }
// a victory in a Raider Camp level 5+: small chance to find one of the missing pieces
function rollDrop(tl){ const p=partChance(tl); if(!p || Math.random()>=p) return null;
  const miss=EQ_SLOTS.filter(s=>!titanState().parts[s]); return miss[Math.floor(Math.random()*miss.length)]||null; }
function findPart(s){ const T=titanState(); if(!EQ_NAME[s] || T.parts[s]) return; T.parts[s]=1;
  const rp=curBase()==='op', n=armorCount();
  setTimeout(()=>toast(IC.drop+' '+_t(rp?'Rampart Titan armor piece found: {p} ({n} / 4)':'Titan armor piece found: {p} ({n} / 4)',{p:_t(EQ_NAME[s]),n})), 1200);
  if(n===4) setTimeout(()=>toast(IC.titan_ic+' '+_t(rp?'Armor complete: your Rampart Titan can now go into battle!':'Armor complete: your Titan can now go into battle!')), 3600); }
function titanPanel(){
  const T=titanState(), st=titanStats(), need=xpNeed(T.lvl), stage=titanStage();
  let h=`<div class="hd"><div class="big tbig"><img class="bimg" src="${titanImg()}" alt=""></div><div style="flex:1">
      <h2>${titanName()} · ${_t('Lv')} ${T.lvl} / ${titanMax()}</h2><div class="sub">${_t(['Prototype','Armored'][stage])} · ${IC.power} ${fmtN(titanPower())} ${_t('power')}</div>
      <div class="sub">${!armorDone()?IC.lock+' '+_t('Armor incomplete'):T.away?IC.atk+' '+_t('On a mission'):T.hp<30?IC.repair+' '+_t('Too damaged to fight (30% needed)'):IC.ok+' '+_t('Ready for battle')}</div></div></div>
    <div class="tbar"><span>XP</span><div class="prog"><i style="width:${Math.min(100,T.xp/need*100)}%"></i></div><small>${fmtN(T.xp)} / ${fmtN(need)}</small></div>
    <div class="tbar"><span>${IC.hp}</span><div class="prog hpb"><i style="width:${Math.floor(T.hp)}%"></i></div><small>${Math.floor(T.hp)}% · +${repairRate()}%/h</small></div>
    ${T.lvl>=titanMax()?`<div class="why">${_t(curBase()==='op'?'Upgrade the Rampart Hangar to raise the maximum level.':'Upgrade the Titan Hangar to raise the maximum level.')}</div>`:''}
    ${curBase()==='op'?`<div class="sub">${IC.def} ${_t('At home and fit to fight, it reinforces the Wall of your main base: defense +{p}%.',{p:Math.round(0.03*T.lvl*100)})}</div>`:''}
    <div class="ust" style="margin:8px 0"><span>${IC.atk} ${fmtN(st.at)}</span><span>${IC.def} ${fmtN(st.df)}</span><span>${IC.hp} ${fmtN(st.hp)}</span><span>${IC.spd} ${st.sp}</span><span>${IC.load} ${fmtN(st.ld)}</span><span>${IC.troops} +${Math.round(titanTroopBonus()*100)}% ${_t('troop attack')}</span></div>
    <h3>${_t(curBase()==='op'?'Rampart Titan armor':'Titan armor')} · ${armorCount()} / 4</h3>
    ${armorDone()?`<div class="why okk">${IC.ok} ${_t('Armor complete: your Titan can go into battle.')}</div>`:`<div class="why">${IC.lock} ${_t('Without its full armor, the Titan cannot go into battle.')}</div>`}
    <div class="eqgrid">${EQ_SLOTS.map(s=>{ const got=!!T.parts[s]; return `<div class="eqslot">${partIcon(s,got,58)}<b>${_t(EQ_NAME[s])}</b><small style="color:${got?'var(--ok)':'var(--mut)'}">${_t(got?'Found':'Missing')}</small></div>`; }).join('')}</div>
    ${curBase()==='op' ? `<p class="sub" style="margin-top:6px">${_t('The pieces of the Rampart Titan are found only by winning against Fortified Mountains: {p}% chance per victory.',{p:Math.round(RP_CHANCE*100)})}</p><button class="sec sm" data-act="gofort">${IC.map} ${_t('Nearest')}</button>`
    : `<p class="sub" style="margin-top:6px">${_t('The pieces are found only by winning against Raider Camps level 5 and up. Chance per victory:')}</p>
    <div class="chips">${Object.keys(ARMOR_CHANCE).map(l=>`<span class="chip">${_t('Lv')} ${l} · ${Math.round(ARMOR_CHANCE[l]*100)} %</span>`).join('')}</div>`}
    <h3>${_t('Appearance')}</h3><div class="tlooks">${[[0,_t('Prototype'),_t('Without armor')],[1,_t('Armored'),_t('{n} / 4 armor pieces',{n:armorCount()})]]
      .map(([k,n,d])=>`<div class="tlook${stage===k?' on':''}${stage<k?' lock':''}"><img src="${(curBase()==='op'?TITAN_STAGES_OP:TITAN_STAGES)[k]}" alt=""><b>${n}</b><small>${d}</small></div>`).join('')}</div>`;
  return h; }
