renderAll=inView(renderAll); renderRes=inView(renderRes); renderQueue=inView(renderQueue); renderSlots=inView(renderSlots); renderSheet=inView(renderSheet); buildWorld=inView(buildWorld); renderDock=inView(renderDock);
