  const bb=(btn.dataset.base==='op' && state.op) ? 'op' : btn.dataset.base==='main' ? 'main' : curBase();   // a line of the activity window may be about the other base
  if(a==='finish') withBase(bb, ()=>{ if(state.queue) complete(); });
