  if(a==='train'){ const u=btn.dataset.unit; Promise.resolve(withBase(cur==='__unit'?trainLoc:curBase(), ()=>train(u, trainQty[u]||0))).then(()=>{ if(cur==='__unit' && unitCloseAfter && !(trainQty[u]>0)) unitBack(); }); }
  if(a==='max'||a==='tclear'||a==='tstep'){ const u=btn.dataset.unit, m=withBase(cur==='__unit'?trainLoc:curBase(), ()=>maxTrain(u)); trainQty[u]= a==='max' ? m : a==='tclear' ? 0 : Math.max(0,Math.min(Math.max(m,trainQty[u]||0),(trainQty[u]||0)+(+btn.dataset.d))); syncQty(u); }
