  if(a==='menu'){ const m=MENU[+btn.dataset.i];
    if(typeof m[2]==='function') m[2]();
    else { closeSheet(); toast(_t('Coming in a future update')); } }
  if(a==='lang') setLang(btn.dataset.l);
