// ===== PAN & ZOOM (mouse, touch, pinch) =====
const vp=document.getElementById('viewport');
let sc=1, tx=0, ty=0, downT=null, moved=0, pinch=null; const ptrs=new Map();
const vsize=()=>({w:vp.clientWidth,h:vp.clientHeight});
// responsive zoom limit: the picture fills the screen; only a screen much wider than the picture (21:9 without wide art)
// or a phone held upright may zoom out further, the empty sides then show a blurred copy of the picture
const minS=()=>{ const v=vsize(), contain=Math.min(v.w/W,v.h/H), cover=Math.max(v.w/W,v.h/H);
  if(v.h>v.w) return cover;   // phone held upright: the picture fills the screen, slide to see the rest
  return v.w/v.h > (W/H)*1.15 ? contain : cover; };
function apply(){ const v=vsize(); sc=Math.min(1.6,Math.max(minS(),sc));
  tx = W*sc<=v.w ? (v.w-W*sc)/2 : Math.min(0,Math.max(v.w-W*sc,tx));   /* smaller than the screen: centred over the blurred backdrop */
  ty = H*sc<=v.h ? (v.h-H*sc)/2 : Math.min(0,Math.max(v.h-H*sc,ty));
  world.style.transform=`translate(${tx}px,${ty}px) scale(${sc})`;
  // smooth while moving (the base is moved as one picture), then drawn again sharp at the new zoom once it stops
  if(world.style.willChange!=='transform') world.style.willChange='transform';
  clearTimeout(sharpT); sharpT=setTimeout(()=>{ world.style.willChange='auto'; }, 220); }
let sharpT=0;
function zoomAt(f,cx,cy){ const ns=Math.min(1.6,Math.max(minS(),sc*f)), k=ns/sc; tx=cx-(cx-tx)*k; ty=cy-(cy-ty)*k; sc=ns; apply(); }
vp.addEventListener('pointerdown',e=>{
  if(e.target.closest('#zoom,#reset,.coordbox')) return;
  vp.setPointerCapture(e.pointerId); ptrs.set(e.pointerId,{x:e.clientX,y:e.clientY});
  if(ptrs.size===1){ downT=e.target; moved=0; } else { downT=null; pinch=null; }
});
vp.addEventListener('pointermove',e=>{
  const p=ptrs.get(e.pointerId); if(!p) return;
  if(ptrs.size===1){ const dx=e.clientX-p.x, dy=e.clientY-p.y; moved+=Math.abs(dx)+Math.abs(dy); if(view==='map') mapPan(dx,dy); else { tx+=dx; ty+=dy; apply(); } if(moved>8) vp.classList.add('drag'); }
  p.x=e.clientX; p.y=e.clientY;
  if(ptrs.size===2){ const [a,b]=[...ptrs.values()], r=vp.getBoundingClientRect(), d=Math.hypot(a.x-b.x,a.y-b.y), mx=(a.x+b.x)/2-r.left, my=(a.y+b.y)/2-r.top;
    if(pinch){ if(view==='map'){ mapZoomAt(d/pinch.d,mx,my); mapPan(mx-pinch.mx,my-pinch.my); } else { zoomAt(d/pinch.d,mx,my); tx+=mx-pinch.mx; ty+=my-pinch.my; apply(); } } pinch={d,mx,my}; }
});
function up(e){
  if(!ptrs.has(e.pointerId)) return; ptrs.delete(e.pointerId); if(ptrs.size<2){ pinch=null; if(view==='map') zoomRelease(); }   // pinch over: the map is drawn sharp again
  if(ptrs.size===0){ vp.classList.remove('drag'); if(view==='map'){ if(downT && moved<8){ const r=vp.getBoundingClientRect(), [x,y]=tapToCell(e.clientX-r.left,e.clientY-r.top); if(x>=1&&y>=1&&x<=MAPN&&y<=MAPN){ mapSel={x,y}; drawMap(); openPanel('__tile'); } } downT=null; return; } if(downT && moved<8 && downT.closest){ const g=downT.closest('[data-slot]'); if(downT.closest('[data-titan]')) openTitan(); else if(g) openSlot(g.dataset.slot); else { const go=downT.closest('[data-goto]'); if(go) setView(go.dataset.goto); } } downT=null; }
}
vp.addEventListener('pointerup',up); vp.addEventListener('pointercancel',up);
const zoomAny=(f,x,y)=>view==='map'?mapZoomAt(f,x,y):zoomAt(f,x,y);
// ---- the page must never be zoomed by the phone browser (some browsers ignore "no zoom"): block it, and undo it if it happens anyway
document.addEventListener('gesturestart', e=>e.preventDefault(), {passive:false});            // iPhone pinch
document.addEventListener('touchmove', e=>{ if(e.touches.length>1 && !e.target.closest('#viewport')) e.preventDefault(); }, {passive:false});
function unzoomPage(){ const vv=window.visualViewport; if(!vv || vv.scale<=1.01) return;
  const m=document.querySelector('meta[name=viewport]'); if(!m) return; const c='width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no';
  m.setAttribute('content', c+',minimum-scale=1'); setTimeout(()=>{ m.setAttribute('content', c); window.scrollTo(0,0); }, 50); }
if(window.visualViewport){ window.visualViewport.addEventListener('resize', unzoomPage); window.visualViewport.addEventListener('scroll', ()=>{ if(window.visualViewport.scale<=1.01 && (window.visualViewport.offsetLeft||window.visualViewport.offsetTop)) window.scrollTo(0,0); }); }
setInterval(unzoomPage, 2000);
vp.addEventListener('wheel',e=>{ e.preventDefault(); const r=vp.getBoundingClientRect(); zoomAny(e.deltaY<0?1.12:1/1.12,e.clientX-r.left,e.clientY-r.top); },{passive:false});
document.getElementById('zin').onclick=()=>{ const v=vsize(); zoomAny(1.2,v.w/2,v.h/2); };
document.getElementById('zout').onclick=()=>{ const v=vsize(); zoomAny(1/1.2,v.w/2,v.h/2); };
window.addEventListener('resize',()=>{ apply(); if(view==='map'){ resizeMap(); drawMap(); } });

// ===== GAME LOOP =====
function tick(){
  const now=Date.now(), dt=Math.max(0,(now-state.last)/1000); state.last=now; const c=cap(), rt=rates();
  if(state.op){ const ac=alloyCap(), a=state.res.alloy||0; if(a<ac) state.res.alloy=Math.min(ac, a+rt.alloy*dt/3600); }   // Heavy Alloy: its own storage, the outpost Warehouse
  for(const r of RES){
    if(r==='gold'){ state.res.gold+=rt.gold*dt/3600; continue; }   // gold has no storage limit
    if(state.res[r]<c) state.res[r]=Math.min(c, state.res[r]+rt[r]*dt/3600);   // production stops when the Warehouse is full;
    // loot, crates and refunds can go above it (overcapacity): nothing is lost, production simply waits
  }

  if(ONLINE){ if(dueOnServer()) syncState(); }   // the server decides what is finished (and gives the level rewards)
  else { for(const bs of baseList()) withBase(bs, ()=>{ if(state.queue && now>=state.queue.end) complete(); checkTraining(); }); checkResearch(); processMarches(); checkLevelUp(); }
  for(const bs of baseList()) withBase(bs, ()=>{ const T=titanState(); if(!T.away && T.hp<100 && hangarLvl()) T.hp=Math.min(100, T.hp+repairRate()*dt/3600); });   // both Titans are repaired in their hangar
  updateRepBadge(); drawClock(); renderTuto(); if(view==='map' && state.marches.length) requestDraw();
  renderRes(); renderQueue(); if(state.queue) renderSlots();
  if(cur==='__wheel' && !wheelSpinning){ const e=document.getElementById('wcd'); if(e){ if(dailyReady()) renderSheet(); else e.textContent=fmtT(secsToMidnight(Date.now())); } }
  if(cur && cur!=='__admin' && cur!=='__menu' && cur!=='__wheel'){ const ae=document.activeElement; // don't rebuild the panel while the player is typing a number
    if(ae && ae.tagName==='INPUT' && document.getElementById('sheet').contains(ae)) liveSheet(); else renderSheet(); }
  save();
}
function centerOn(x,y){ const v=vsize(); sc=Math.max(minS(), v.w<600?0.5:0.7); tx=v.w/2-(x+OX)*sc; ty=v.h/2-y*sc; apply(); }
(function(){ const av=document.getElementById('avatar'); av.style.backgroundImage=`url(${PORTRAIT}), radial-gradient(circle at 50% 35%,#55663f,#1c2318)`; av.style.backgroundSize='135%, cover'; av.style.backgroundPosition='45% 8%, center'; })();
document.querySelectorAll('img[data-ic]').forEach(i=>{ i.src=ICS[i.dataset.ic]; });
(function(){ const F={"fr_btn": "assets/img/fr_btn.webp", "fr_bar": "assets/img/fr_bar.webp", "fr_win": "assets/img/fr_win.webp", "fr_slot": "assets/img/fr_slot.webp"};
  for(const k in F) document.documentElement.style.setProperty('--'+k.replace('_','-'), `url(${new URL(F[k], location.href).href})`); })();

// =====================================================================
// ===== ONLINE: player accounts and saves on the Bastion server =====
// When the game is opened from the Bastion server, the player logs in and the game is saved there.
// Opened from anywhere else (GitHub Pages, a file), it stays an offline demo saved in the browser.
// =====================================================================
var ONLINE=false, NET={token:null, name:null, dirty:false, pushing:false, others:new Map()};
const TOKEN_KEY='bastion_token';
// the mark of the game page on every request (the server refuses game orders without it: scripts are forbidden)
function pageSig(token){ let h1=0xdeadbeef^77, h2=0x41c6ce57^77; const s=token+'|bastion-play';
  for(let i=0;i<s.length;i++){ const c=s.charCodeAt(i); h1=Math.imul(h1^c,2654435761); h2=Math.imul(h2^c,1597334677); }
  h1=Math.imul(h1^(h1>>>16),2246822507)^Math.imul(h2^(h2>>>13),3266489909);
  h2=Math.imul(h2^(h2>>>16),2246822507)^Math.imul(h1^(h1>>>13),3266489909);
  return (h2>>>0).toString(16).padStart(8,'0')+(h1>>>0).toString(16).padStart(8,'0'); }
// the account was blocked for using a script: back to the login screen with the reason
let bannedShown=false;
function playerBanned(j){ if(bannedShown) return; bannedShown=true;
  if(streamCtl){ streamCtl.abort(); streamCtl=null; } try{ localStorage.removeItem(TOKEN_KEY); }catch(e){} NET.token=null;
  showLogin(banMsg(j)); }
// blocked by the administrator: his reason is shown (written by him, so escaped)
const banMsg = j => j && j.error==='banned_admin' ? _t(LOGIN_ERR.banned_admin)+(j.motif?' '+_t('Reason: {m}',{m:esc(j.motif)}):'') : _t(LOGIN_ERR.banned);
// disconnected from the management panel: back to the login screen
function playerKicked(){ if(bannedShown) return; bannedShown=true;
  if(streamCtl){ streamCtl.abort(); streamCtl=null; } try{ localStorage.removeItem(TOKEN_KEY); }catch(e){} NET.token=null;
  showLogin(_t('You were disconnected by the administrator.')); }
async function apiCall(method, url, body){
  const r = await fetch(url, {method, headers:Object.assign({'Content-Type':'application/json'}, NET.token?{Authorization:'Bearer '+NET.token, 'X-Bastion':pageSig(NET.token)}:{}), body: body?JSON.stringify(body):undefined, cache:'no-store', keepalive: method==='PUT'});
  let j={}; try{ j=await r.json(); }catch(e){}
  noteServerTime(r);
  if((j.error==='banned' || j.error==='banned_admin') && NET.token) playerBanned(j);
  if(j.error==='old_page'){ location.reload(); }   // a page from before an update: the new one loads
  if(j.error==='maintenance' && j.srv) srvStatus(j.srv);   // the game went into maintenance: the maintenance screen shows
  if(!r.ok){ const e=new Error(j.error||('http_'+r.status)); e.status=r.status; e.motif=j.motif; throw e; }
  return j; }
function pushSave(force){
  if(!ONLINE || !NET.token || NET.pushing || (!NET.dirty && !force)) return;
  NET.pushing=true; NET.dirty=false;
  apiCall('PUT','api/state',{state, lvl:playerLevel(totalPower()), power:totalPower()})
    .catch(e=>{ NET.dirty=true; if(e.status===401) logout(true); })
    .finally(()=>{ NET.pushing=false; }); }
async function loadPlayers(){
  if(!ONLINE || !NET.token) return;
  try{ const j=await apiCall('GET','api/players'); const m=new Map(); for(const p of j.players) m.set(p.x*1024+p.y, p);
    if(Array.isArray(j.outposts) && setOutposts(j.outposts) && view==='map') requestDraw();
    // only the bases that changed are redrawn (no full refresh of the map every minute)
    const now=Date.now(), sig=p=>p ? [p.lvl,p.name,(p.shield||0)>now,p.alliance||''].join('|') : '', old=NET.others||new Map(), cells=[];
    for(const k of new Set([...old.keys(), ...m.keys()])) if(sig(old.get(k))!==sig(m.get(k))) cells.push([Math.floor(k/1024), k%1024]);
    NET.others=m; invalidateCells(cells); if(view==='map' && cells.length) requestDraw(); }catch(e){} }
function logout(expired){ if(bannedShown) return;   // blocked: the login screen already says why
  if(streamCtl){ streamCtl.abort(); streamCtl=null; }
  if(NET.token) apiCall('POST','api/logout').catch(()=>{});
  try{ localStorage.removeItem(TOKEN_KEY); }catch(e){}
  NET.token=null; if(expired) alertLogin(_t('Your session has expired, please log in again.')); else location.reload(); }
let alertLogin=()=>location.reload();
// ---- live line with the server: an attack launched against us shows at once (banner + siren), results arrive at once
let streamCtl=null, streamOn=false;
async function openStream(){
  if(!ONLINE || !NET.token || streamCtl) return;
  const ctl=new AbortController(); streamCtl=ctl;
  try{ const r=await fetch('api/stream',{headers:{Authorization:'Bearer '+NET.token}, signal:ctl.signal, cache:'no-store'});
    if(!r.ok || !r.body) throw new Error('stream');
    streamOn=true; const rd=r.body.getReader(), dec=new TextDecoder(); let buf='';
    for(;;){ const {value,done}=await rd.read(); if(done) break; buf+=dec.decode(value,{stream:true});
      let i; while((i=buf.indexOf('\n\n'))>=0){ const blk=buf.slice(0,i); buf=buf.slice(i+2); onStream(blk); } } }
  catch(e){}
  streamOn=false; if(streamCtl===ctl) streamCtl=null;
  if(ONLINE && NET.token && !ctl.signal.aborted) setTimeout(openStream, 3000); }   // cut (server restart, network): reconnects by itself
function onStream(blk){ let ev='message', data='';
  for(const l of blk.split('\n')){ if(l.startsWith('event:')) ev=l.slice(6).trim(); else if(l.startsWith('data:')) data+=l.slice(5).trim(); }
  if(!data) return; let j; try{ j=JSON.parse(data); }catch(e){ return; }
  if(ev==='incoming') setIncoming(j.incoming); else if(ev==='sync') syncState(true); else if(ev==='reload') location.reload(); else if(ev==='banned') playerBanned(j);
  else if(ev==='srv') srvStatus(j); else if(ev==='kick') playerKicked(); }   // srv: maintenance, countdown, announcement · kick: disconnected by the administrator   // reload: new rights given from the server console
const LOGIN_ERR = {bad_name:'The name must have 3 to 16 letters, numbers, spaces, - or _.', bad_password:'The password must have at least 6 characters.', name_taken:'This name is already taken.',
  bad_login:'Wrong name or password.', too_many:'Too many tries. Wait a few minutes.', bad_request:'Server error. Try again later.', server_error:'Server error. Try again later.',
  too_many_accounts:'Too many new accounts from this connection today. Try again tomorrow.', too_fast:'Too many orders at once. Wait a moment.',
  banned:'This account is blocked: scripts and automated programs are forbidden.', banned_admin:'This account is blocked by the administrator.',
  test_closed:'Registrations are closed on the test server.', maintenance:'The game is under maintenance. Try again in a few minutes.'};
function showLogin(msg){
  let ov=document.getElementById('login'); if(ov) ov.remove();
  ov=document.createElement('div'); ov.id='login';
  ov.innerHTML=`<div class="lbox"><div class="ltitle">BASTION</div><div class="lsub">${_t('Military strategy · near future')}</div>
    <div class="ltabs"><button class="on" data-lt="login">${_t('Log in')}</button><button data-lt="register">${_t('Create an account')}</button></div>
    <input id="lname" maxlength="16" autocomplete="username" placeholder="${_t('Commander name')}">
    <input id="lpass" type="password" maxlength="100" autocomplete="current-password" placeholder="${_t('Password')}">
    <input id="lpass2" type="password" maxlength="100" autocomplete="new-password" placeholder="${_t('Repeat the password')}" style="display:none">
    <div class="lerr" id="lerr">${msg||''}</div>
    <div class="lrule">${_t('Scripts and automated programs are forbidden: accounts using them are blocked.')}</div>
    <button class="lgo" id="lgo">${_t('Log in')}</button>
    <select id="llang">${LANGS.map(([c,n])=>`<option value="${c}"${c===LANG?' selected':''}>${n}</option>`).join('')}</select></div>`;
  document.body.appendChild(ov); testBanner(SRV.test);
  let mode='login';
  const q=id=>ov.querySelector('#'+id), err=t=>{ q('lerr').textContent=t; };
  ov.querySelectorAll('[data-lt]').forEach(b=>b.onclick=()=>{ mode=b.dataset.lt; ov.querySelectorAll('[data-lt]').forEach(x=>x.classList.toggle('on',x===b));
    q('lpass2').style.display=mode==='register'?'':'none'; q('lpass').autocomplete=mode==='register'?'new-password':'current-password'; q('lgo').textContent=_t(mode==='register'?'Create an account':'Log in'); err(''); });
  q('llang').onchange=e=>{ LANG=e.target.value; try{ localStorage.setItem('bastion_lang',LANG); }catch(x){} applyStatic(); showLogin(); };
  const go=async()=>{ const name=q('lname').value.trim(), password=q('lpass').value;
    if(mode==='register' && password!==q('lpass2').value) return err(_t('The two passwords are different.'));
    q('lgo').disabled=true;
    try{ const j=await apiCall('POST', mode==='register'?'api/register':'api/login', {name,password});
      NET.token=j.token; bannedShown=false; try{ localStorage.setItem(TOKEN_KEY,j.token); }catch(x){} ov.remove(); await enterOnline(); }
    catch(e){ if(e.message==='banned_admin') q('lerr').innerHTML=banMsg({error:e.message, motif:e.motif}); else err(_t(LOGIN_ERR[e.message]||'Cannot reach the server.')); q('lgo').disabled=false; } };
  q('lgo').onclick=go; ov.addEventListener('keydown',e=>{ if(e.key==='Enter') go(); });
  setTimeout(()=>q('lname').focus(),50); }
async function enterOnline(){
  let j; try{ j=await apiCall('GET','api/state'); }catch(e){ if(e.message==='banned') return; if(e.status===401){ try{ localStorage.removeItem(TOKEN_KEY); }catch(x){} NET.token=null; return showLogin(); } return showLogin(_t('Cannot reach the server.')); }
  NET.name=j.name; NET.role=j.role||'player'; document.body.classList.toggle('notest', !isStaff());
  const st=j.state; st.pos=j.pos; state=st; normalizeState(); resetTiles(); mcam=null;
  goOnlineOrders(); loaderShow(); await pingBurst(); await loadPlayers(); await preloadMap(); startGame(); loaderHide(); lastSync=Date.now();
  setInterval(()=>syncState(true), 30000); setInterval(ping, 10000); setInterval(loadPlayers, 60000); setInterval(pollIncoming, 8000);   // the checks stay as a safety net
  openStream();   // live line: alerts arrive instantly
  if(j.incoming) setIncoming(j.incoming); NET.beginner=j.beginner||0;
  document.addEventListener('visibilitychange',()=>{ if(document.visibilityState==='visible') syncState(true); });
  toast(IC.ok+' '+_t('Welcome, commander {n}!',{n:NET.name})); setTimeout(maybeNews, 1200); }
async function boot(){
  let h=null; if(location.protocol.startsWith('http') && !/github\.io$/.test(location.hostname)){ try{ const r=await fetch('api/health',{cache:'no-store'}); if(r.ok) h=await r.json(); }catch(e){} }
  if(!h || h.game!=='Bastion'){ await preloadMap(); startGame(); loaderHide(); setTimeout(maybeNews, 1200); return; }       // offline demo
  ONLINE=true; alertLogin=m=>showLogin(m); SRV.test=!!h.test; testBanner(SRV.test);
  try{ NET.token=localStorage.getItem(TOKEN_KEY); }catch(e){}
  if(NET.token) enterOnline(); else showLogin(); }

// =====================================================================
// ===== QUESTS AND TUTORIAL (the server checks them and gives the rewards) =====
// =====================================================================
function questState(){ if(!state.quests) state.quests={done:{}}; return state.quests; }
function statsState(){ if(!state.stats) state.stats={wins:(state.reports||[]).filter(r=>r.win).length, campWins:(state.reports||[]).filter(r=>r.win&&r.tt==='camp').length}; return state.stats; }
const countType = t => Object.values(state.slots).filter(b=>b.type===t).length;
const armySize = () => { const D=defenseState(), mm=marching(); let n=0; for(const u in UNITS) n+=(state.troops[u]||0)+(D[u]||0)+(mm[u]||0); return n; };
const techTotal = () => { let n=0; for(const t in TECH) n+=techLv(t); return n; };
const firstSlot = (t) => { for(const k in state.slots) if(state.slots[k].type===t) return k; return null; };
const emptySlot = (field) => { const s=SLOTS.find(s=>!s.fixed && slotUsable(s) && !!s.view===!!field && !state.slots[s.id] && !(state.queue&&state.queue.slot===s.id)); return s&&s.id; };
const bImg = t => t==='wall' ? wallIcon() : B[t].img || ICS.build;
// where "Go" takes the player
function goBuild(t, b){ showBase(b||'main'); const k=firstSlot(t) || (SLOTS.find(s=>slotFixed(s)===t)||{}).id || emptySlot(!!B[t].field); if(!k) return; const s=SLOTS.find(x=>x.id===k);
  setView(s.view==='fields'?'fields':'city'); hintSlot=k; centerOn(s.x, s.y); openSlot(k); }
function goAttack(){ setView('map'); for(let r=2;r<40;r+=2) for(let dx=-r;dx<=r;dx+=2){ const x=state.pos.x+dx,y=state.pos.y+r, t=tileAt(x,y); if(t&&t.t==='camp'&&t.lvl===1){ camCenter(x,y); mapSel={x,y}; drawMap(); openPanel('__tile'); return; } } }
// q(id, category, title, progress, reward, go, icon)
const QUESTS=[];
const Q_=(id,cat,title,prog,reward,go,icon)=>QUESTS.push({id,cat,title,prog:()=>withBase('main',prog),reward,go,icon});   // progress always counted with the main base active
const R=(res,items)=>({res:res||{}, items:items||{}});
