    const steps = kind==='attack' ? [[620,0],[880,.28],[620,.56],[880,.84],[620,1.12]] : [[1200,0],[0,.12],[1200,.24],[0,.36]];
    for(const [f,t] of steps){ if(f) o.frequency.setValueAtTime(f,t0+t); g.gain.setValueAtTime(f?0.07:0, t0+t); }
