  el.addEventListener('click',e=>{ const b=e.target.closest('[data-i]'); if(!b) return; if(b.dataset.i==='go') doInstall(); else { try{ localStorage.setItem('bastion_noinstall',String(Date.now())); }catch(x){} el.remove(); } });
