const hourAt = ts => { const opt={hour:'2-digit',minute:'2-digit'}; if(CLOCK.tz) opt.timeZone=CLOCK.tz; try{ return new Intl.DateTimeFormat(LANG,opt).format(new Date(ts)); }catch(e){ return new Date(ts).toLocaleTimeString(); } };
