const NEWS_KEY='bastion_news';
function newsDate(d){ try{ return new Date(d+'T12:00:00').toLocaleDateString(LANG,{day:'numeric',month:'long',year:'numeric'}); }catch(e){ return d; } }
function newsPanel(){
  let h=`<div class="hd"><div class="big">${IC.news}</div><div style="flex:1;min-width:0"><h2>${_t("What's new")}</h2><div class="sub">${_t('The latest updates of Bastion.')}</div></div></div>`;
  PATCH.forEach((p,i)=>{ h+=`<div class="pnote${i?'':' last'}"><div class="pnh">${i?'':`<span class="pnew">${_t('New')}</span>`}<b>${_t('Update of {d}',{d:newsDate(p.d)})}</b></div>
    <ul>${p.items.map(t=>`<li>${_t(t)}</li>`).join('')}</ul></div>`; });
  return h+`<button class="pok" data-act="close">${IC.ok} ${_t('Got it')}</button>`; }
function openNews(){ try{ localStorage.setItem(NEWS_KEY, PATCH[0].id); }catch(e){} openPanel('__news'); sheetTop(); }
// once per update: shown when the game opens if this player has not seen the newest notes on this device
function maybeNews(){ let seen=null; try{ seen=localStorage.getItem(NEWS_KEY); }catch(e){}
  if(seen===PATCH[0].id || document.getElementById('login') || cur) return; openNews(); }
// =====================================================================
// ===== LOADING: everything the map needs is prepared before the game shows (no stutter on the first slides) =====
// =====================================================================
function loaderShow(){ let el=document.getElementById('loader'); if(el) return el;
  el=document.createElement('div'); el.id='loader';
  el.innerHTML=`<div class="ldbox"><div class="ltitle">BASTION</div><div class="ldtxt" id="ldtxt">${_t('Preparing the map...')}</div><div class="ldbar"><i id="ldbar"></i></div><div class="ldpct" id="ldpct">0 %</div></div>`;
  document.body.appendChild(el); return el; }
function loaderStep(p, txt){ const b=document.getElementById('ldbar'), n=document.getElementById('ldpct'), t=document.getElementById('ldtxt');
  if(b) b.style.width=Math.round(p*100)+'%'; if(n) n.textContent=Math.round(p*100)+' %'; if(txt && t) t.textContent=txt; }
function loaderHide(){ const el=document.getElementById('loader'); if(!el) return; el.classList.add('out'); setTimeout(()=>el.remove(), 400); }
const nextFrame = () => new Promise(r=>setTimeout(r,0));
const KEEP_IMGS=[];   // decoded pictures kept alive so the browser does not throw them away
async function preloadMap(){
  loaderShow();
  // 1. every picture of the map, decoded once (the first drawing of an image is what makes a phone stutter)
  const imgs=[...new Set([...Object.values(MIMG), gImg, starImg, crownImg])]; let done=0;
  await Promise.all(imgs.map(im=>(im.complete && im.naturalWidth ? (im.decode?im.decode():Promise.resolve()) : new Promise(r=>{ im.addEventListener('load',r,{once:true}); im.addEventListener('error',r,{once:true}); setTimeout(r,15000); }).then(()=>im.decode&&im.naturalWidth?im.decode():null))
    .catch(()=>{}).then(()=>{ done++; loaderStep(0.6*done/imgs.length); })));
  try{ if(document.fonts) await Promise.race([document.fonts.ready, new Promise(r=>setTimeout(r,3000))]); }catch(e){}
  badgeCache.clear();
  // the pictures of the base, the fields and the troops too: switching views is then instant
  loaderStep(0.6, _t('Loading the base...'));
  const urls=[...new Set([bgNow(), FBG, ...Object.keys(B).map(t=>bImgAt(t,bldLevel(t)||1).img), ...Object.values(UNITS).map(u=>u.img)].filter(Boolean))];
  KEEP_IMGS.length=0; done=0;
  await Promise.all(urls.map(u=>{ const im=new Image(); KEEP_IMGS.push(im); im.src=u; return (im.decode?im.decode():Promise.resolve()).catch(()=>{}).then(()=>{ done++; loaderStep(0.6+0.1*done/urls.length); }); }));
  // 2. the map around the base, drawn in advance at the starting zoom (the screen, plus a ring all around)
  if(!mcam){ mcam={x:0,y:0,z:vsize().w<600?0.55:0.75}; camCenter(state.pos.x,state.pos.y); }
  const d=mapDpr(), V=viewChunks(1), todo=[];
  chunkMax=Math.max(chunkMax, (V.cx1-V.cx0+3)*(V.cy1-V.cy0+3));
  for(let cy=V.cy0; cy<=V.cy1; cy++) for(let cx=V.cx0; cx<=V.cx1; cx++) todo.push([cx,cy]);
  loaderStep(0.7, _t('Drawing the map around your base...'));
  lastHomeLvl=playerLevel(totalPower());
  for(let i=0;i<todo.length;i++){ const [cx,cy]=todo[i], k=cx+','+cy+','+V.zb+','+d;
    if(!chunkCache.has(k)){ const ch=renderChunk(cx,cy,V.zb,d); if(ch.ok) putChunk(k,ch); }
    loaderStep(0.7+0.3*(i+1)/todo.length); await nextFrame(); }
  loaderStep(1); }
function startGame(){ applyStatic(); buildWorld(); centerOn(1300,640); tick(); renderAll(); if(!tickTimer) tickTimer=setInterval(tick,1000); }
if(typeof __SERVER==='undefined') boot();   // the server runs these rules without any screen: no start-up there
